class Table {

    static void printTable(int n) {
        synchronized (Table.class) {   // class-level lock
            for (int i = 1; i <= 5; i++) {
                System.out.println(n * i);
                try {
                    Thread.sleep(400);
                } catch (Exception e) {
                    System.out.println(e);
                }
            }
        }
    }
}

class MyThread extends Thread {
    int n;

    MyThread(int n) {
        this.n = n;
    }

    public void run() {
        Table.printTable(n);
    }
}

public class Main {
    public static void main(String[] args) {
        MyThread t1 = new MyThread(5);
        MyThread t2 = new MyThread(100);

        t1.start();
        t2.start();
    }
}
